using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// Load API key from environment
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

// Build the chat client via MEAI abstraction
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient("gpt-4o-mini-2024-07-18")
    .AsIChatClient();

// Define the tools available to the agent
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearch.SearchAsync),
    AIFunctionFactory.Create(Notebook.TakeNote),
    AIFunctionFactory.Create(Notebook.GetNotes),
};

// Create the research agent with system instructions
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web for relevant information (perform multiple searches to cover different angles).
        2. Take notes on key findings as you go.
        3. After gathering enough information, retrieve all your notes and produce a concise summary.
        Always cite your sources. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "Researches topics by searching the web and summarizing findings.",
    tools: tools);

// Get the research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent
var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    options: new ChatClientAgentRunOptions(new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    }));

// Display the result
Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine(response.Text);
Console.WriteLine("═══════════════════════════════════════");

if (response.Usage is { } usage)
{
    Console.WriteLine($"\n[Tokens used — Input: {usage.InputTokenCount}, Output: {usage.OutputTokenCount}]");
}

// --- Tool implementations ---

/// <summary>Simulates web search results for the agent.</summary>
static class WebSearch
{
    private static readonly HttpClient Http = new();

    [Description("Searches the web for information on a query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public static async Task<string> SearchAsync(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        // Use a real search API if available, otherwise simulate results
        // In production, replace with Bing Search API, Google Custom Search, etc.
        await Task.Delay(100, cancellationToken); // Simulate network latency

        return $"""
            Search results for: "{query}"

            1. [Wikipedia] Overview of {query}
               Snippet: {query} is a widely discussed topic with multiple facets covering technology, science, and industry applications.
               URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}

            2. [Research Paper] Recent advances in {query}
               Snippet: A 2024 survey covering the latest developments, challenges, and future directions in {query}.
               URL: https://arxiv.org/search/?query={Uri.EscapeDataString(query)}

            3. [News] Latest developments in {query}
               Snippet: Industry experts weigh in on how {query} is transforming practices and what to expect next.
               URL: https://news.example.com/{Uri.EscapeDataString(query)}
            """;
    }
}

/// <summary>Provides note-taking capabilities for the agent to organize research findings.</summary>
static class Notebook
{
    private static readonly List<string> Notes = [];

    [Description("Takes a note to remember a key finding or piece of information during research.")]
    public static string TakeNote(
        [Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"  📝 Note taken ({Notes.Count} total)");
        return $"Note saved. You now have {Notes.Count} note(s).";
    }

    [Description("Retrieves all notes taken so far during the research session.")]
    public static string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes taken yet.";

        Console.WriteLine($"  📋 Retrieving {Notes.Count} notes");
        return string.Join("\n\n", Notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

